import { FormControl } from '@angular/forms';
export const showError = (control) => {
    return (control?.invalid && (control?.touched || control?.dirty)) || false;
};
export const newFormControlByType = (type = 'text', isMultipleFile = false) => {
    if (type === 'radio' ||
        type === 'checkbox' ||
        type === 'phone' ||
        type === 'number' ||
        type === 'switch')
        return new FormControl(null);
    if (type === 'file')
        return new FormControl(isMultipleFile ? [null] : null);
    return new FormControl('');
};
export const assignNewFormControl = (name, control, type = 'text', isMultipleFile = false) => {
    if (!control) {
        console.warn(`[bmb-input - ${name}] -`, 'The assigned control was not valid, a new formControl was generated.');
        return newFormControlByType(type, isMultipleFile);
    }
    return null;
};
export const handleValidity = (control) => {
    control.updateValueAndValidity();
    control.markAsTouched();
};
